package com.networkzero.screens;

import com.badlogic.gdx.*;import com.badlogic.gdx.graphics.*;import com.badlogic.gdx.graphics.g2d.*;import com.badlogic.gdx.graphics.glutils.ShapeRenderer;import com.badlogic.gdx.scenes.scene2d.*;import com.badlogic.gdx.scenes.scene2d.ui.*;import com.badlogic.gdx.scenes.scene2d.utils.*;import com.badlogic.gdx.utils.*;import com.badlogic.gdx.utils.viewport.*;import com.badlogic.gdx.graphics.g2d.freetype.*;import com.badlogic.gdx.math.Matrix4;import com.networkzero.*;import com.networkzero.story.StoryScreen;import com.networkzero.story.EndingController;import com.networkzero.engine.*;

public final class LandingScreen implements Screen {
    private static final float VW=1920,VH=1080; private final Game game; private final FitViewport viewport=new FitViewport(VW,VH); private final SpriteBatch batch=new SpriteBatch(); private final ShapeRenderer shapes=new ShapeRenderer(); private final Stage stage=new Stage(viewport); private final SettingsManager settings=new SettingsManager(); private final AudioManager audio=new AudioManager(); private final Atmosphere atmosphere=new Atmosphere(); private Texture bg; private BitmapFont title,small; private Skin skin; private float elapsed,fade=1; private boolean debug,scan; private final Label status;
    public LandingScreen(Game game){this.game=game;settings.load();audio.setVolume(settings.music);audio.fadeIn(1);try{String image="landing/landing_bg.png",titleFont="fonts/Silkscreen-Bold.ttf",bodyFont="fonts/Silkscreen-Regular.ttf";if(!Gdx.files.internal(image).exists())throw new IllegalStateException("Required asset missing: assets/landing/landing_bg.png");if(!Gdx.files.internal(titleFont).exists())throw new IllegalStateException("Required font missing: assets/fonts/Silkscreen-Bold.ttf");if(!Gdx.files.internal(bodyFont).exists())throw new IllegalStateException("Required font missing: assets/fonts/Silkscreen-Regular.ttf");bg=new Texture(Gdx.files.internal(image));bg.setFilter(Texture.TextureFilter.Nearest,Texture.TextureFilter.Nearest);FreeTypeFontGenerator.FreeTypeFontParameter p=new FreeTypeFontGenerator.FreeTypeFontParameter();p.size=43;p.magFilter=Texture.TextureFilter.Nearest;p.minFilter=Texture.TextureFilter.Nearest;p.borderWidth=2;p.borderColor=new Color(.025f,.035f,.05f,1);FreeTypeFontGenerator gen=new FreeTypeFontGenerator(Gdx.files.internal(titleFont));title=gen.generateFont(p);gen.dispose();p.size=18;p.borderWidth=0;gen=new FreeTypeFontGenerator(Gdx.files.internal(bodyFont));small=gen.generateFont(p);gen.dispose();}catch(Exception e){Gdx.app.error("NETWORK ZERO",e.getMessage(),e);throw new GdxRuntimeException(e.getMessage(),e);}skin=buildSkin();Gdx.input.setInputProcessor(stage);status=new Label("",skin);buildUi();}
    private Skin buildSkin(){
        Skin s=new Skin(); BitmapFont f=small; s.add("default-font",f);
        TextureRegionDrawable panel=solid(.035f,.045f,.06f,.96f), outline=solid(.88f,.35f,.13f,1), knob=solid(1,.48f,.16f,1), track=solid(.18f,.21f,.23f,1);
        Label.LabelStyle label=new Label.LabelStyle(f,new Color(.92f,.91f,.84f,1));s.add("default",label);
        TextButton.TextButtonStyle button=new TextButton.TextButtonStyle();button.font=f;button.fontColor=new Color(.94f,.91f,.82f,1);button.overFontColor=Color.ORANGE;button.up=panel;button.over=outline;button.down=outline;s.add("default",button);
        Window.WindowStyle window=new Window.WindowStyle(f,Color.ORANGE,panel);s.add("default",window);
        TextField.TextFieldStyle field=new TextField.TextFieldStyle();field.font=f;field.fontColor=Color.WHITE;field.cursor=knob;field.selection=outline;field.background=panel;s.add("default",field);
        Slider.SliderStyle slider=new Slider.SliderStyle();slider.background=track;slider.knob=knob;s.add("default-horizontal",slider);
        CheckBox.CheckBoxStyle check=new CheckBox.CheckBoxStyle();check.font=f;check.fontColor=Color.WHITE;check.checkboxOff=panel;check.checkboxOn=knob;s.add("default",check);
        return s;
    }
    private TextureRegionDrawable solid(float r,float g,float b,float a){Pixmap p=new Pixmap(1,1,Pixmap.Format.RGBA8888);p.setColor(r,g,b,a);p.fill();Texture t=new Texture(p);p.dispose();t.setFilter(Texture.TextureFilter.Nearest,Texture.TextureFilter.Nearest);return new TextureRegionDrawable(new TextureRegion(t));}
    private void buildUi(){Table root=new Table();root.setFillParent(true);root.top().left().pad(360,115,0,0);root.defaults().width(430).height(70).padBottom(10);continueAvailable=java.nio.file.Files.isRegularFile(ProfilePaths.saves().resolve("room1_state.json"))||java.nio.file.Files.isRegularFile(ProfilePaths.saves().resolve("room2_state.json"))||java.nio.file.Files.isRegularFile(ProfilePaths.saves().resolve("room3_state.json"));java.util.ArrayList<String> names=new java.util.ArrayList<>();names.add("NEW GAME");if(continueAvailable)names.add("CONTINUE");names.add("SETTINGS");names.add("EXIT");for(int i=0;i<names.size();i++){final int n=i;TextButton b=new TextButton(names.get(i),skin);b.getLabel().setAlignment(Align.left);b.padLeft(22);b.addListener(new InputListener(){public void enter(InputEvent e,float x,float y,int p,Actor a){audio.play("hover");}public boolean touchDown(InputEvent e,float x,float y,int p,int button){b.setScale(.97f);return true;}public void touchUp(InputEvent e,float x,float y,int p,int button){b.setScale(1);if(!b.isDisabled())select(n);}});root.add(b).row();}stage.addActor(root);status.setPosition(110,85);stage.addActor(status);TextButton back=new TextButton("BACK",skin);back.setPosition(110,110);back.addListener(new ClickListener(){public void clicked(InputEvent e,float x,float y){Gdx.input.setInputProcessor(stage);}});}
    private void select(int n){audio.play("click");if(n==0){modeDialog();return;}int resume=SaveCheck.continueRoom();if(n==1&&continueAvailable){if(resume==2||resume==3){com.networkzero.room.GameState s=Room3Screen.loadSavedState();game.setScreen(new Room3Screen(game,new com.networkzero.session.LocalSession(s,settings.playerName,null),true));return;}if(resume==1){game.setScreen(new RoomScreen(game,true));return;}status.setText("There is no unfinished game to continue.");return;}if(continueAvailable){if(n==2){settingsDialog();return;}if(n==3)Gdx.app.exit();}else{if(n==1){settingsDialog();return;}if(n==2)Gdx.app.exit();}}
    private Dialog dialog(String titleText){Dialog d=new Dialog(titleText,skin);d.setModal(true);d.setMovable(false);d.setSize(680,560);d.setPosition((VW-680)/2,(VH-560)/2);d.getTitleLabel().setColor(Color.ORANGE);d.pad(24);return d;}
    private void modeDialog(){Dialog d=dialog("START SESSION");d.getContentTable().add(new Label("Choose your session",skin)).pad(14).row();addDialogButton(d,"PLAY SOLO",()->game.setScreen(settings.skipStory?new RoomScreen(game,false):new StoryScreen(game)));addDialogButton(d,"HOST CO-OP (LAN)",()->game.setScreen(new LobbyScreen(game,GameMode.HOST)));addDialogButton(d,"JOIN CO-OP (LAN)",()->game.setScreen(new LobbyScreen(game,GameMode.JOIN)));d.button("BACK",false);d.key(Input.Keys.ESCAPE,false);d.show(stage);}
    private void addDialogButton(Dialog d,String text,Runnable action){TextButton b=new TextButton(text,skin);d.getContentTable().add(b).width(440).height(54).pad(5).row();b.addListener(new ClickListener(){public void clicked(InputEvent e,float x,float y){d.hide();action.run();}});}
    private void settingsDialog(){Dialog d=dialog("SETTINGS");Slider music=new Slider(0,1,.05f,false,skin),sfx=new Slider(0,1,.05f,false,skin);music.setValue(settings.music);sfx.setValue(settings.sfx);CheckBox full=new CheckBox(" Fullscreen",skin);full.setChecked(settings.fullscreen);CheckBox skip=new CheckBox(" Skip story (testing)",skin);skip.setChecked(settings.skipStory);TextField name=new TextField(settings.playerName,skin);name.setMaxLength(16);d.getContentTable().add("Music volume").pad(6);d.getContentTable().add(music).width(300).row();d.getContentTable().add("SFX volume").pad(6);d.getContentTable().add(sfx).width(300).row();d.getContentTable().add(full).colspan(2).pad(8).row();d.getContentTable().add(skip).colspan(2).pad(6).row();d.getContentTable().add("Player name").pad(6);d.getContentTable().add(name).width(300).row();addDialogButton(d,"REPLAY STORY",()->game.setScreen(new StoryScreen(game)));addDialogButton(d,"REPLAY ENDING",()->EndingController.playEnding(game,()->{LandingScreen l=new LandingScreen(game);game.setScreen(l);l.settingsDialog();}));music.addListener(new ChangeListener(){public void changed(ChangeEvent e,Actor a){settings.music=music.getValue();audio.setVolume(settings.music);settings.save();}});full.addListener(new ChangeListener(){public void changed(ChangeEvent e,Actor a){settings.fullscreen=full.isChecked();if(settings.fullscreen)Gdx.graphics.setFullscreenMode(Gdx.graphics.getDisplayMode());else Gdx.graphics.setWindowedMode(1280,720);settings.save();}});skip.addListener(new ChangeListener(){public void changed(ChangeEvent e,Actor a){settings.skipStory=skip.isChecked();settings.save();}});d.button("SAVE",true).button("CANCEL",false);d.show(stage);d.getButtonTable().getCells().get(0).getActor().addListener(new ClickListener(){public void clicked(InputEvent e,float x,float y){settings.playerName=name.getText();settings.sfx=sfx.getValue();settings.skipStory=skip.isChecked();settings.save();d.hide();}});}
    private void devRoomSelect(){Dialog d=dialog("DEV ROOM SELECT");addDialogButton(d,"NETWORKING LABORATORY",()->game.setScreen(new RoomScreen(game,false)));addDialogButton(d,"NETWORK CONTROL OFFICE",()->game.setScreen(new Room3Screen(game,new com.networkzero.session.LocalSession(new com.networkzero.room.GameState(),settings.playerName,null),false)));addDialogButton(d,"ENDING",()->EndingController.playEnding(game,()->game.setScreen(new LandingScreen(game))));d.button("BACK",false);d.key(Input.Keys.ESCAPE,false);d.show(stage);}
    public void render(float dt){dt=Math.min(dt,.05f);elapsed+=dt;fade=Math.max(0,fade-dt);atmosphere.update(dt);audio.update(dt);ScreenUtils.clear(.015f,.02f,.03f,1);viewport.apply();batch.setProjectionMatrix(viewport.getCamera().combined);batch.begin();float scale=Math.max(VW/bg.getWidth(),VH/bg.getHeight());float w=bg.getWidth()*scale,h=bg.getHeight()*scale;batch.setColor(1,1,1,1);batch.draw(bg,(VW-w)/2,(VH-h)/2,w,h);batch.end();shapes.setProjectionMatrix(new Matrix4().setToOrtho2D(0,0,VW,VH));atmosphere.draw(shapes,false);drawLogo();if(fade>0){shapes.begin(ShapeRenderer.ShapeType.Filled);shapes.setColor(0,0,0,fade);shapes.rect(0,0,VW,VH);shapes.end();}if(debug)drawDebug();if(continueAvailable&&SaveCheck.continueRoom()==0){Actor rootActor=stage.getActors().first();if(rootActor instanceof Table t)for(Actor a:t.getChildren())if(a instanceof TextButton b&&b.getText().toString().equals("CONTINUE")){b.setDisabled(true);b.getLabel().setColor(Color.GRAY);}}stage.act(dt);stage.draw();if(Gdx.input.isKeyJustPressed(Input.Keys.F11)){settings.fullscreen=!settings.fullscreen;if(settings.fullscreen)Gdx.graphics.setFullscreenMode(Gdx.graphics.getDisplayMode());else Gdx.graphics.setWindowedMode(1280,720);settings.save();}if(Gdx.input.isKeyJustPressed(Input.Keys.F1))debug=!debug;if(Gdx.input.isKeyJustPressed(Input.Keys.F2))status.setText("Landing effects reloaded");if(Gdx.input.isKeyJustPressed(Input.Keys.F9))devRoomSelect();if(Gdx.input.isKeyJustPressed(Input.Keys.ESCAPE)&&stage.getActors().size>0){for(Actor a:stage.getActors())if(a instanceof Dialog)((Dialog)a).hide();}}
    private void drawLogo(){batch.begin();float x=100,y=920;title.setColor(.94f,.93f,.85f,1);title.draw(batch,"NETWORK",x,y);title.setColor(1,.43f,.14f,1);title.draw(batch,"ZERO",x,y-80);small.setColor(.72f,.72f,.68f,1);small.draw(batch,"THE LAST LAB SESSION",x,y-126);batch.end();}
    private void drawDebug(){shapes.setProjectionMatrix(new Matrix4().setToOrtho2D(0,0,VW,VH));shapes.begin(ShapeRenderer.ShapeType.Line);shapes.setColor(Color.GREEN);shapes.rect(1635,455,285,600);shapes.rect(1635,440,285,590);shapes.rect(1350,375,210,590);shapes.end();}
    private int keyboardFocus=0; private boolean continueAvailable;
    private void navigate(int key){Actor first=stage.getActors().first();if(!(first instanceof Table table))return;Array<Actor> actors=table.getChildren();if(key==Input.Keys.UP||key==Input.Keys.DOWN){int dir=key==Input.Keys.UP?-1:1;for(int tries=0;tries<actors.size;tries++){keyboardFocus=(keyboardFocus+dir+actors.size)%actors.size;Actor a=actors.get(keyboardFocus);if(a instanceof TextButton b&&!b.isDisabled())break;}}else if(key==Input.Keys.ENTER&&keyboardFocus<actors.size&&actors.get(keyboardFocus) instanceof TextButton b&&!b.isDisabled())select(keyboardFocus);}
    private void reloadTuning(){try{JsonValue root=new JsonReader().parse(Gdx.files.internal("data/landing.json"));atmosphere.configure(root);scan=root.getBoolean("scanlines",false);}catch(Exception e){status.setText("Could not reload data/landing.json");Gdx.app.error("NETWORK ZERO","Could not reload landing tuning",e);}}
    public void resize(int w,int h){viewport.update(w,h,true);stage.getViewport().update(w,h,true);}public void show(){reloadTuning();Gdx.input.setInputProcessor(new InputMultiplexer(new InputAdapter(){@Override public boolean keyDown(int key){if(key==Input.Keys.UP||key==Input.Keys.DOWN||key==Input.Keys.ENTER){navigate(key);return true;}if(key==Input.Keys.F2){reloadTuning();return true;}return false;}},stage));}public void hide(){}public void pause(){}public void resume(){}
    public void dispose(){stage.dispose();batch.dispose();shapes.dispose();if(bg!=null)bg.dispose();if(title!=null)title.dispose();skin.dispose();audio.close();}
}
